from __future__ import absolute_import

import time

from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By

from taf.selenium.sbts.common.exceptions import NoSuchHwElement
from taf.selenium.sbts.pages import v23r3, v23r4
from taf.selenium.sbts.pages.modals import StartUplaneComponentTraceFailed
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.panels.view import ViewPanel


class Diagnostic(v23r4.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._rf_scan = RfScanPage(driver, download_checker)

    @property
    def rf_scan(self):
        return self._rf_scan


class DebugTracingPage(v23r3.diagnostic.DebugTracingPage):
    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_l1_stream(self, configurations):
        self._view_panel.configure_l1_stream(configurations)

    def start_l1_stream_component_trace_and_return_result(self):
        return self._view_panel.start_l1_stream_component_trace_and_return_result()

    def stop_l1_stream_component_trace_and_return_result(self, cells):
        return self._view_panel.stop_l1_stream_component_trace_and_return_result(cells)


class DebugTracingPageViewPanel(v23r3.diagnostic.DebugTracingPageViewPanel):
    _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH = '//section[@class="uPlane-component"]//div[contains(text(), "{}")]'
    _LTE_CELL_IDS_DROPDOWN_BUTTON = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//button'
    _LTE_CELL_IDS_OPTIONS = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//input[@type="checkbox"]'
    _ACTIVATE_INTERNAL_TRACE_BUTTON = '//execution-bar//button[contains(text(), "Activate")]'
    _DEACTIVATE_INTERNAL_TRACE_BUTTON = '//execution-bar//button[contains(text(), "Deactivate")]'
    _INTERNAL_TRACE_STATUS_XPATH = ('//execution-bar//ui-button//following-sibling::*'
                                    '//span[not(contains(@class, "icon"))]')

    _SOURCE_IP = '//div[div[contains(text(), "Source IP")]]//input'
    _DSCP = '//div[div[contains(text(), "DSCP")]]//input'
    _UPLAN_DEST_IP = '(//div[div[contains(text(), "UPlane destination")]]//input)[1]'
    _UPLAN_DEST_PORT = '(//div[div[contains(text(), "UPlane destination")]]//input)[2]'

    _ADD_CELL_BUTTON = '//u-plane-component//l1-stream//button[contains(text(), "Add Cell")]'
    _CELL_DATA_BODY = '//u-plane-component//l1-stream//tree-table//tbody'
    _NO_CELLS = _CELL_DATA_BODY + '//tr[contains(@class, "no-data")]//td[text()="No cells"]'
    _CELL_ITEM = _CELL_DATA_BODY + '//tr[@aria-hidden="false"]'
    _TRASH_BUTTON = _CELL_ITEM + '//ui-button[@a-icon="trash"]//button'
    _LAST_CELL_ITEM = _CELL_ITEM + "[last()]"
    _PENULTIMATE_CELL_ITEM = _CELL_ITEM + "[last()-1]"
    _START_TRACES = '//u-plane-component//*[@class="l1-stream-control"]//button[contains(text(), "Start Traces")]'
    _STOP_TRACES = '//u-plane-component//*[@class="l1-stream-control"]//button[contains(text(), "Stop Traces")]'
    _SELECTED_CELL = _CELL_DATA_BODY + '//input[@checked="checked"]'
    _SELECTED_NAME_BY_TRASH = _CELL_DATA_BODY + '//ui-button[@a-icon="trash"]//button/ancestor::tr//td[2]//button//span[@title]'
    _SELECTED_CELL_BY_TRASH = _CELL_DATA_BODY + '//ui-button[@a-icon="trash"]//button/ancestor::tr'
    _TRACE_RESULT = _SELECTED_CELL_BY_TRASH + "//td[6]"

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def _input_cell_ids(self, cell_ids_lable, cells_ids):
        if not cells_ids:
            return
        elem = self.wait_for_enable(self._LTE_CELL_IDS_DROPDOWN_BUTTON.format(cell_ids_lable))
        self._scroll_elem_into_view(elem, "start", "nearest")
        self.click_enabled_element((By.XPATH, self._LTE_CELL_IDS_DROPDOWN_BUTTON.format(cell_ids_lable)))
        self._choose_value_if_checkbox_exist(
            self._LTE_CELL_IDS_OPTIONS.format(cell_ids_lable),
            cells_ids
        )
        self.click_enabled_element((By.XPATH, self._LTE_CELL_IDS_DROPDOWN_BUTTON.format(cell_ids_lable)))

    def _choose_value_if_checkbox_exist(self, check_box_xpath, value):
        """
        Choose checkbox according to given value
        :param check_box_xpath: str, xpath
        :param value: list, list contains str value
        """
        value = [str(item) for item in value]
        for index, _ in enumerate(self.driver.find_elements_by_xpath(check_box_xpath)):
            element = self.driver.find_elements_by_xpath(check_box_xpath)[index]
            is_checked = element.is_selected()
            span_item = element.find_element_by_xpath('./following-sibling::label')
            self._scroll_elem_into_view(span_item, "start", "nearest")
            if not is_checked and span_item.text in value:
                span_item.click()
            elif is_checked and span_item.text not in value:
                span_item.click()

    def configure_l1_stream(self, configuration):
        self._configuration = configuration
        self._scroll_elem_into_view(self.driver.find_element_by_xpath(self._L1_STREAM_XPATH), "start", "nearest")
        self.click_enabled_element((By.XPATH, self._L1_STREAM_XPATH))
        self.wait_for_visibility((By.XPATH, self._ADD_CELL_BUTTON))

        self._clear_existed_configuration()
        self._configure_l1_stream(configuration)

    def _clear_existed_configuration(self):
        trash_button = self.driver.find_elements_by_xpath(self._TRASH_BUTTON)
        if len(trash_button) != 0:
            for _ in self.driver.find_elements_by_xpath(self._TRASH_BUTTON):
                trash_elem = self.driver.find_elements_by_xpath(self._TRASH_BUTTON)[-1]
                self.driver.execute_script('arguments[0].click();', trash_elem)
                time.sleep(0.3)
        self.wait_for_visibility((By.XPATH, self._NO_CELLS))

    def _configure_l1_stream(self, configuration):
        for index, l1_stream in enumerate(configuration):
            self.click_enabled_element((By.XPATH, self._ADD_CELL_BUTTON))
            time.sleep(1)

            select_xpath = self._LAST_CELL_ITEM + "//td[1]//label"
            self.click_enabled_element((By.XPATH, select_xpath))

            cell = l1_stream["Cell"]
            cell_button = self._LAST_CELL_ITEM + "//td[2]//button"
            cell_option = self._LAST_CELL_ITEM + "//td[2]//ul//li//span[text()='{}']"
            self.click_enabled_element((By.XPATH, cell_button))
            self.driver.execute_script('arguments[0].click();',
                                       self.driver.find_element_by_xpath(cell_option.format(cell)))

            output_mode = l1_stream["Output mode"]
            output_mode_button = self._PENULTIMATE_CELL_ITEM + "//td[3]//button"
            output_mode_option = self._PENULTIMATE_CELL_ITEM + "//td[3]//ul//li//span[text()='{}']"
            self.click_enabled_element((By.XPATH, output_mode_button))
            self.driver.execute_script('arguments[0].click();',
                                       self.driver.find_element_by_xpath(output_mode_option.format(output_mode)))

            l1_trace_id = l1_stream["L1 trace ID"]
            l1_trace_id_input = self._LAST_CELL_ITEM + "//td[4]//input"
            self.insert_text_to_enable_element((By.XPATH, l1_trace_id_input), l1_trace_id)

            sub_type = l1_stream["Sub type"]
            sub_type_input = self._LAST_CELL_ITEM + "//td[5]//input"
            self.insert_text_to_enable_element((By.XPATH, sub_type_input), sub_type)

            reports_number = l1_stream["Number of reports"]
            reports_number_input = self._LAST_CELL_ITEM + "//td[6]//input"
            self.insert_text_to_enable_element((By.XPATH, reports_number_input), reports_number)

    def start_l1_stream_component_trace_and_return_result(self):
        self.click_enabled_element((By.XPATH, self._START_TRACES))
        modal = StartUplaneComponentTraceFailed(self.driver)
        try:
            modal.wait_until_start_uplane_component_trace_failed_modal_appear(timeout=1)
            return modal.cancel()
        except TimeoutException:
            pass

        self._wait_for_start_or_stop_completed(self._SELECTED_CELL, "(" + self._SELECTED_CELL + ")[{}]")

        return self._get_start_or_stop_status([item["Cell"] for item in self._configuration], self._TRACE_RESULT)

    def stop_l1_stream_component_trace_and_return_result(self, cells):
        number_of_cells = len(self.driver.find_elements_by_xpath(self._SELECTED_NAME_BY_TRASH))
        cells_name = []
        for index in range(1, number_of_cells + 1):
            selected_cell_name = "(" + self._SELECTED_NAME_BY_TRASH + ')[{}]'.format(index)
            cells_name.append(self.driver.find_element_by_xpath(selected_cell_name).text)
            if self.driver.find_element_by_xpath(selected_cell_name).text not in cells:
                selected_tr = "(" + self._SELECTED_CELL_BY_TRASH + ')[{}]'.format(index) + '//td[1]//label'
                self.click_enabled_element((By.XPATH, selected_tr))

        self.click_enabled_element((By.XPATH, self._STOP_TRACES))

        self._wait_for_start_or_stop_completed(self._SELECTED_CELL_BY_TRASH,
                                               "(" + self._SELECTED_CELL_BY_TRASH + "//td[1]//input)[{}]")

        for index in range(1, number_of_cells + 1):
            selected_tr = "(" + self._SELECTED_CELL_BY_TRASH + ')[{}]'.format(index) + '//td[1]//input'
            if not self.driver.find_element_by_xpath(selected_tr).is_selected():
                self.driver.execute_script('arguments[0].click();', self.driver.find_element_by_xpath(selected_tr))

        return self._get_start_or_stop_status(cells_name, self._TRACE_RESULT)

    def _wait_for_start_or_stop_completed(self, selected_cell_xpath, status_xpath):
        number_of_cells = len(self.driver.find_elements_by_xpath(selected_cell_xpath))
        count = 0
        for _ in range(10):
            for index in range(1, number_of_cells + 1):
                try:
                    self.wait_for_text_not_present_in_attribute(status_xpath.format(index), "disabled", "true", 0.5)
                    count += 1
                except TimeoutException:
                    pass

            if count == number_of_cells:
                break
        time.sleep(3)

    def _get_start_or_stop_status(self, cells_name, status_xpath):
        number_of_cells = len(cells_name)
        outcome = {}
        for index in range(number_of_cells):
            result = self.driver.find_elements_by_xpath(status_xpath)[index].text
            outcome.update({cells_name[index]: result})
        return outcome


class RfScanPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Diagnostic", "RF Monitoring", "RF Scan"]

    def __init__(self, driver, download_checker):
        super(RfScanPage, self).__init__(driver)
        self._view_panel = RfScanPageViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_rf_scan(self, technology, radio, capture_type, antenna, antenna_panel=None, local_cell=None, timeout=60):
        self._view_panel.start_rf_scan(technology, radio, capture_type, antenna, antenna_panel, local_cell, timeout)

    def cancel_rf_scan(self, timeout=60):
        return self._view_panel.cancel_rf_scan(timeout)

    def download_rf_scan_files(self, download_timeout):
        return self._view_panel.download_rf_scan_files(download_timeout)


class RfScanPageViewPanel(ViewPanel):
    _TECHNOLOGY_BUTTON = '//div[*[contains(text(), "Technology")]]//button'
    _TECHNOLOGY_OPTION = '//div[*[contains(text(), "Technology")]]//li'

    _NO_DATA = '//table[contains(@class, "antenna-to-be-scanned-table")]//tbody//td[@colspan="5"]'

    _BASE_BUTTON = ('//table[contains(@class, "antenna-to-be-scanned-table")]//tbody//td[contains(@class, "{}")]'
                    '//button')
    _BASE_OPTION = ('//table[contains(@class, "antenna-to-be-scanned-table")]//tbody//td[contains(@class, "{}")]'
                    '//li')
    _RADIO_BUTTON = _BASE_BUTTON.format("radios")
    _RADIO_OPTION = _BASE_OPTION.format("radios")

    _CAPTURE_TYPE_BUTTON = _BASE_BUTTON.format("capture-type")
    _CAPTURE_TYPE_OPTION = _BASE_OPTION.format("capture-type")

    _ANTENNA_BUTTON = _BASE_BUTTON.format("antenna")
    _ANTENNA_OPTION = _BASE_OPTION.format("antenna")

    _ANTENNA_PANEL_BUTTON = _BASE_BUTTON.format("antenna-panel")
    _ANTENNA_PANEL_OPTION = _BASE_OPTION.format("antenna-panel")

    _LOCAL_CELL_BUTTON = _BASE_BUTTON.format("local-cell")
    _LOCAL_CELL_OPTION = _BASE_OPTION.format("local-cell")

    _START = '//rf-monitoring-progress//button[contains(text(), "Start")]'
    _CANCEL = '//rf-monitoring-progress//button[contains(text(), "Cancel")]'
    _PROGRESS_BAR = '//*[contains(@class, "rf-monitoring-progress-info")]'
    _DOWNLOADING = "Testing and downloading files from BTS"
    _DOWNLOADED = "Download completed and file saved"
    _CANCELING = "Cancelling"
    _CANCELED = "Canceled"

    def __init__(self, driver, download_checker):
        super(RfScanPageViewPanel, self).__init__(driver, download_checker)
        self._start_time = None

    def start_rf_scan(self, technology, radio, capture_type, antenna, antenna_panel=None, local_cell=None, timeout=60):

        self.select_element_from_dropdown_list_by_text_and_click(technology,
                                                                 (By.XPATH, self._TECHNOLOGY_BUTTON),
                                                                 (By.XPATH, self._TECHNOLOGY_OPTION),
                                                                 timeout)

        if self.element_exists((By.XPATH, self._NO_DATA)):
            raise NoSuchHwElement("No any radio under {}".format(technology))

        self.select_element_from_dropdown_list_by_text_and_click(radio,
                                                                 (By.XPATH, self._RADIO_BUTTON),
                                                                 (By.XPATH, self._RADIO_OPTION),
                                                                 timeout)

        self.select_element_from_dropdown_list_by_text_and_click(capture_type,
                                                                 (By.XPATH, self._CAPTURE_TYPE_BUTTON),
                                                                 (By.XPATH,
                                                                  self._CAPTURE_TYPE_OPTION),
                                                                 timeout)

        self.select_element_from_dropdown_list_by_text_and_click(antenna,
                                                                 (By.XPATH, self._ANTENNA_BUTTON),
                                                                 (By.XPATH, self._ANTENNA_OPTION),
                                                                 timeout)

        if antenna_panel is not None:
            self.select_element_from_dropdown_list_by_text_and_click(antenna_panel,
                                                                     (By.XPATH, self._ANTENNA_PANEL_BUTTON),
                                                                     (By.XPATH,
                                                                      self._ANTENNA_PANEL_OPTION),
                                                                     timeout)

        if "Carrier" in capture_type:
            self.select_element_from_dropdown_list_by_text_and_click(local_cell,
                                                                     (By.XPATH, self._LOCAL_CELL_BUTTON),
                                                                     (By.XPATH,
                                                                      self._LOCAL_CELL_OPTION),
                                                                     timeout)

        self._start_time = time.time()
        self.click_enabled_element((By.XPATH, self._START), timeout)

    def cancel_rf_scan(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CANCEL), timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._PROGRESS_BAR), self._CANCELING, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._PROGRESS_BAR), self._CANCELED, timeout)
        return self.get_text_by_xpath(self._PROGRESS_BAR)

    def download_rf_scan_files(self, download_timeout=120):
        try:
            self.wait_for_text_present_in_element((By.XPATH, self._PROGRESS_BAR), self._DOWNLOADED, download_timeout)
        except TimeoutException:
            return self.get_text_by_xpath(self._PROGRESS_BAR)
        return self.download_files(self._start_time, download_timeout)
